                <span className="font-serif text-[21px] transition-colors group-hover:text-accent lg:w-48 lg:shrink-0 lg:text-[26px]">
                  {g.category}
                </span>
                <span className="hidden flex-1 gap-3 lg:flex" aria-hidden>
