import type { Offer, RetailerId } from "../types";
import { RETAILER_LABELS } from "../types";

const SEARCH_URLS: Record<RetailerId, (q: string) => string> = {
  amazon: (q) => `https://www.amazon.com/s?k=${encodeURIComponent(q)}`,
  walmart: (q) => `https://www.walmart.com/search?q=${encodeURIComponent(q)}`,
  target: (q) => `https://www.target.com/s?searchTerm=${encodeURIComponent(q)}`,
};

/** An honest fallback when we have no real product: a link to the store's own search. */
export function searchLinkOffer(retailer: RetailerId, query: string): Offer {
  return {
    retailer,
    externalId: `search:${retailer}:${query.toLowerCase()}`,
    title: `Search ${RETAILER_LABELS[retailer]} for “${query}”`,
    price: null,
    imageUrl: null,
    url: SEARCH_URLS[retailer](query),
    rating: null,
    inStock: true,
  };
}

import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

/**
 * Target has no public product-search API for affiliates. Instead we create a
 * tracked search deep link through the Target Partners (Impact) link set in
 * TARGET_IMPACT_LINK, e.g. https://goto.target.com/c/<pid>/<adid>/2092
 */
export const targetProvider: RetailerProvider = {
  id: "target",
  isConfigured() {
    return Boolean(process.env.TARGET_IMPACT_LINK);
  },
  async search(query) {
    const destination = `https://www.target.com/s?searchTerm=${encodeURIComponent(query)}&category=5xtly`;
    const url = `${process.env.TARGET_IMPACT_LINK}?u=${encodeURIComponent(destination)}`;
    return [
      {
        retailer: "target",
        externalId: `search:${query.toLowerCase()}`,
        title: `${query} at Target`,
        price: null,
        imageUrl: null,
        url,
        rating: null,
        inStock: true,
      },
    ];
  },
};

